const crypto = require('crypto');

function canonical(value) {
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (value && typeof value === 'object') return '{' + Object.keys(value).sort().map(k => JSON.stringify(k) + ':' + canonical(value[k])).join(',') + '}';
  return JSON.stringify(value);
}

const headers = $json.headers || {};
const envelope = $json.body || {};
const timestamp = String(headers['x-sanolifood-timestamp'] || '');
const supplied = String(headers['x-sanolifood-signature'] || '');
if (!/^\d{10}$/.test(timestamp)) throw new Error('Missing or invalid analyst timestamp');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('Analyst decision is outside the five-minute replay window');
if (envelope.schema_version !== 1) throw new Error('Unsupported analyst decision envelope');
const secret = String($env.SOAR_ANALYST_SECRET || '');
if (secret.length < 32) throw new Error('SOAR analyst secret is unavailable');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + canonical(envelope)).digest('hex');
const expectedBuffer = Buffer.from(expected);
const suppliedBuffer = Buffer.from(supplied);
if (expectedBuffer.length !== suppliedBuffer.length || !crypto.timingSafeEqual(expectedBuffer, suppliedBuffer)) throw new Error('Invalid analyst decision signature');
const decision = String(envelope.decision || '').toLowerCase();
if (!['approve', 'reject'].includes(decision)) throw new Error('Decision must be approve or reject');
if (!/^[0-9a-f-]{36}$/i.test(String(envelope.incident_id || ''))) throw new Error('Invalid incident identifier');
if (!/^[a-zA-Z0-9._@-]{3,128}$/.test(String(envelope.analyst || ''))) throw new Error('Invalid analyst identity');
if (String(envelope.reason || '').trim().length < 8) throw new Error('An analyst justification of at least eight characters is required');
return [{ json: {
  incident_id: String(envelope.incident_id), decision, analyst: String(envelope.analyst), reason: String(envelope.reason).trim(),
  nonce: String(envelope.nonce), requested_at: String(envelope.requested_at)
} }];
